// Recall-mode questions — Essential Equations, constants & units (derived from the MCAT Milesdown deck)
// Format: {s: tag, disc: scoring discipline, q, choices: [4], ans: 0-3, exp, src}
const QB_EQUATIONS = [
  {s:'Physics Equations & Units',disc:'physics',q:'Which expression gives the energy of a single photon in terms of its wavelength?',choices:['E = hc/λ','E = hλ/c','E = λ/(hc)','E = hcλ'],ans:0,exp:'**E = hf = hc/λ**: E is photon energy (J), h = 6.626×10⁻³⁴ J·s is Planck\'s constant, c = 3.00×10⁸ m/s is the speed of light, λ is wavelength (m) and f = c/λ is frequency (Hz). Energy is inversely proportional to wavelength, so UV photons carry more energy than red ones; a units check rejects hλ/c, which comes out in J·s², not J.',src:'milesdown:1553874796649'},
  {s:'Physics Equations & Units',disc:'physics',q:'For constant acceleration, which expression gives final velocity in terms of initial velocity, acceleration and elapsed time?',choices:['v = v₀ + at','v = v₀ + ½at','v = v₀ + at²','v = v₀t + at'],ans:0,exp:'**v = v₀ + at** follows from the definition a = Δv/Δt: v and v₀ are final and initial velocity (m/s), a is acceleration (m/s²) and t is time (s). Units check: at is (m/s²)(s) = m/s, whereas at² is in meters (a displacement), so that form cannot be a velocity.',src:'milesdown:1554137027040'},
  {s:'Physics Equations & Units',disc:'physics',q:'For constant acceleration, which expression relates final velocity to initial velocity, acceleration and displacement (no time given)?',choices:['v² = v₀² + 2aΔx','v² = v₀² + aΔx','v = v₀ + 2aΔx','v² = v₀² + 2aΔt'],ans:0,exp:'**v² = v₀² + 2aΔx** is the "timeless" kinematics equation: v and v₀ are final and initial velocity (m/s), a is acceleration (m/s²) and Δx is displacement (m). MCAT tip: for an object dropped from rest through height h, it gives v = √(2gh); dropping the factor of 2 is the most common slip.',src:'milesdown:1554137059695'},
  {s:'Physics Equations & Units',disc:'physics',q:'For constant acceleration, which expression gives displacement in terms of initial velocity, acceleration and elapsed time?',choices:['Δx = v₀t + ½at²','Δx = v₀t + at²','Δx = v₀ + ½at²','Δx = v₀t + ½at'],ans:0,exp:'**Δx = v₀t + ½at²**: Δx is displacement (m), v₀ is initial velocity (m/s), a is acceleration (m/s²) and t is time (s). Every term must be in meters, which rules out v₀ alone (m/s) and ½at (m/s); the ½ comes from averaging the velocity over the interval.',src:'milesdown:1554137072986'},
  {s:'Physics Equations & Units',disc:'physics',q:'Which expression gives the centripetal acceleration of an object moving at constant speed in a circle?',choices:['a = v²/r','a = v/r','a = v²r','a = r/v²'],ans:0,exp:'**a_c = v²/r**: v is tangential speed (m/s) and r is the radius of the circle (m); the acceleration points toward the center. Units check: (m/s)²/m = m/s². Doubling the speed quadruples the centripetal acceleration, while doubling the radius halves it.',src:'milesdown:1554137084063'},
  {s:'Physics Equations & Units',disc:'physics',q:'Which expression gives the net centripetal force needed to keep a mass moving in a circle?',choices:['F = mv²/r','F = mv/r','F = mv²r','F = ½mv²/r'],ans:0,exp:'**F_c = mv²/r** is Newton\'s second law (F = ma) with a = v²/r: m is mass (kg), v is speed (m/s) and r is radius (m). Centripetal force is not a new kind of force; it is supplied by tension, gravity, friction or a normal force directed toward the center.',src:'milesdown:1554137095740'},
  {s:'Physics Equations & Units',disc:'physics',q:'A projectile is launched with speed v₀ at angle θ above the horizontal. Which expression gives the horizontal component of its initial velocity?',choices:['vₓ = v₀cos θ','vₓ = v₀sin θ','vₓ = v₀tan θ','vₓ = v₀/cos θ'],ans:0,exp:'**vₓ = v₀cos θ**: the horizontal side is adjacent to the launch angle θ, so it takes cosine; v₀ is launch speed (m/s). Ignoring air resistance, vₓ stays constant for the whole flight, so range = vₓ × time of flight; sine gives the vertical component instead.',src:'milesdown:1554146702184'},
  {s:'Physics Equations & Units',disc:'physics',q:'A projectile is launched with speed v₀ at angle θ above the horizontal. Which expression gives the vertical component of its initial velocity?',choices:['v_y = v₀sin θ','v_y = v₀cos θ','v_y = v₀tan θ','v_y = v₀/sin θ'],ans:0,exp:'**v_y = v₀sin θ**: the vertical side is opposite the launch angle θ, so it takes sine; v₀ is launch speed (m/s). Gravity reduces v_y by about 9.8 m/s each second until it reaches zero at the peak, so time to apex = v₀sin θ/g.',src:'milesdown:1554146805163'},
  {s:'Physics Equations & Units',disc:'physics',q:'Which expression is Newton\'s second law, relating net force to mass and acceleration?',choices:['F = ma','F = m/a','F = mv','F = ma²'],ans:0,exp:'**F_net = ma**: F is the net force (N), m is mass (kg) and a is acceleration (m/s²), so 1 N = 1 kg·m/s². The tempting F = mv is momentum (kg·m/s), not force; force is the rate of change of momentum.',src:'milesdown:1554146816489'},
  {s:'Physics Equations & Units',disc:'physics',q:'Which expression states Newton\'s third law for two objects A and B (masses m_A and m_B) pushing on each other?',choices:['F(A on B) = −F(B on A)','F(A on B) = F(B on A)','F(A on B) = −(m_A/m_B)·F(B on A)','F(A on B) = −(m_B/m_A)·F(B on A)'],ans:0,exp:'**F(A on B) = −F(B on A)**: the action–reaction forces are equal in magnitude and opposite in direction, whatever the masses. A common misconception is that the heavier object pushes harder; it does not, the lighter one simply accelerates more (a = F/m). The pair never cancels because the two forces act on different objects.',src:'milesdown:1554146852376'},
  {s:'Physics Equations & Units',disc:'physics',q:'Which expression gives the magnitude of the friction force on a sliding object?',choices:['f = μF_N','f = F_N/μ','f = μF_applied','f = μmg sin θ'],ans:0,exp:'**f = μF_N**: μ is the dimensionless coefficient of friction and F_N is the normal force (N). Kinetic friction is f_k = μ_kF_N; static friction can be anything up to f_s,max = μ_sF_N, and μ_s > μ_k. Friction depends on the normal force, not on how hard you push sideways.',src:'milesdown:1554146934101'},
  {s:'Physics Equations & Units',disc:'physics',q:'Which expression gives the gravitational force between two masses m₁ and m₂ separated by distance r?',choices:['F = Gm₁m₂/r²','F = Gm₁m₂/r','F = Gm₁m₂r²','F = G(m₁ + m₂)/r²'],ans:0,exp:'**F = Gm₁m₂/r²** (Newton\'s law of gravitation): G = 6.67×10⁻¹¹ N·m²/kg², m₁ and m₂ are masses (kg) and r is the center-to-center distance (m). It is an inverse-square law, so doubling r cuts the force to one quarter; Gm₁m₂/r is the (magnitude of) gravitational potential energy, not force.',src:'milesdown:1554146968671'},
  {s:'Physics Equations & Units',disc:'physics',q:'Which expression gives the weight of an object of mass m near Earth\'s surface?',choices:['F = mg','F = m/g','F = mgh','F = ½mg'],ans:0,exp:'**F_g = mg**: m is mass (kg) and g ≈ 9.8 m/s² (round to 10 on the MCAT), giving weight in newtons. mgh is gravitational potential energy (J), not a force; mass stays the same everywhere, but weight changes with g.',src:'milesdown:1554146997703'},
  {s:'Physics Equations & Units',disc:'physics',q:'Which expression gives the torque produced by a force F applied at distance r from a pivot, where θ is the angle between r and F?',choices:['τ = rF sin θ','τ = rF cos θ','τ = F sin θ/r','τ = r²F sin θ'],ans:0,exp:'**τ = rF sin θ**: r is the lever-arm distance from the pivot (m), F is force (N) and θ is the angle between r and F. Torque is greatest when the force is perpendicular (sin 90° = 1) and zero when the force points along the lever arm. Its unit is N·m, which is never written as joules for torque.',src:'milesdown:1554147024841'},
  {s:'Physics Equations & Units',disc:'physics',q:'Which expression gives the work done by a constant force F over a displacement d, where θ is the angle between the force and the displacement?',choices:['W = Fd cos θ','W = Fd sin θ','W = F cos θ/d','W = ½Fd cos θ'],ans:0,exp:'**W = Fd cos θ**: F is force (N), d is displacement (m) and θ is the angle between them, giving work in joules (N·m). Only the force component along the motion does work, so a normal force on a level surface (θ = 90°) does zero work; cosine, not sine, picks out that parallel component.',src:'milesdown:1554147035884'},
  {s:'Physics Equations & Units',disc:'physics',q:'Which pair of expressions correctly gives mechanical power?',choices:['P = W/t = Fv cos θ','P = Wt = Fv cos θ','P = W/t = Fd cos θ','P = W/t = Fv sin θ'],ans:0,exp:'**P = W/t = Fv cos θ**: W is work (J), t is time (s), F is force (N), v is velocity (m/s) and θ is the angle between F and v; power is in watts (J/s). Fd cos θ is just the work itself, and multiplying by time gives the wrong units.',src:'milesdown:1554147045927'},
  {s:'Physics Equations & Units',disc:'physics',q:'Which expression gives the translational kinetic energy of a mass m moving at speed v?',choices:['KE = ½mv²','KE = mv²','KE = ½mv','KE = ½m²v'],ans:0,exp:'**KE = ½mv²**: m is mass (kg) and v is speed (m/s), giving joules (kg·m²/s²). Because of the square, doubling the speed quadruples the kinetic energy; ½mv has momentum-like units, not energy.',src:'milesdown:1554147062543'},
  {s:'Physics Equations & Units',disc:'physics',q:'Which expression gives the elastic potential energy stored in a spring stretched or compressed a distance x from equilibrium?',choices:['U = ½kx²','U = kx²','U = ½kx','U = ½k²x'],ans:0,exp:'**U = ½kx²**: k is the spring constant (N/m) and x is displacement from equilibrium (m), giving joules. The energy is always positive and is the same for a given stretch or compression; ½kx has units of newtons, a force rather than energy (Hooke\'s law is F = −kx).',src:'milesdown:1554147370341'},
  {s:'Physics Equations & Units',disc:'physics',q:'Which expression gives the gravitational potential energy of a mass m at height h near Earth\'s surface?',choices:['U = mgh','U = ½mgh','U = mg/h','U = mgh²'],ans:0,exp:'**U = mgh**: m is mass (kg), g ≈ 9.8 m/s² and h is height above a chosen reference level (m), giving joules. Only changes in U matter, so the zero level can be put wherever is convenient; in a frictionless drop mgh converts fully to ½mv².',src:'milesdown:1554147389334'},
  {s:'Physics Equations & Units',disc:'physics',q:'Which expression gives the gravitational potential energy of two masses M and m separated by a center-to-center distance r?',choices:['U = −GMm/r','U = GMm/r','U = −GMm/r²','U = GMm/r²'],ans:0,exp:'**U = −GMm/r**: G = 6.67×10⁻¹¹ N·m²/kg², M and m are masses (kg) and r is separation (m). The negative sign comes from setting U = 0 at infinite separation, so bound objects have negative potential energy; the 1/r² forms belong to the gravitational force, not the energy.',src:'milesdown:1554147409750'},
  {s:'Physics Equations & Units',disc:'physics',q:'A block of mass m rests on a ramp inclined at angle θ to the horizontal. Which expression gives the component of gravity pulling it down the slope?',choices:['F = mg sin θ','F = mg cos θ','F = mg tan θ','F = mg/sin θ'],ans:0,exp:'**F_parallel = mg sin θ**: m is mass (kg), g ≈ 9.8 m/s² and θ is the incline angle. Mnemonic: "sin is sliding down the slide." Limiting check: at θ = 0 (flat ground) the downhill pull is zero and at θ = 90° it is the full weight mg, which only sine gives.',src:'milesdown:1554147432122'},
  {s:'Physics Equations & Units',disc:'physics',q:'A block of mass m rests on a ramp inclined at angle θ to the horizontal. Which expression gives the normal force on the block (no other forces perpendicular to the ramp)?',choices:['F_N = mg cos θ','F_N = mg sin θ','F_N = mg tan θ','F_N = mg/cos θ'],ans:0,exp:'**F_N = mg cos θ**: the normal force balances the component of weight perpendicular to the ramp; m is mass (kg), g ≈ 9.8 m/s² and θ is the incline angle. Limiting check: on flat ground (θ = 0) F_N = mg, and it shrinks as the ramp steepens; mg/cos θ would wrongly grow.',src:'milesdown:1554147509483'},
  {s:'Physics Equations & Units',disc:'physics',q:'A block of mass m slides on a ramp inclined at angle θ with friction coefficient μ. Which expression gives the friction force?',choices:['f = μmg cos θ','f = μmg sin θ','f = μmg','f = mg cos θ/μ'],ans:0,exp:'**f = μmg cos θ** because friction is μ times the normal force, and on an incline F_N = mg cos θ; μ is dimensionless, m is mass (kg) and g ≈ 9.8 m/s². Using μmg forgets that the ramp carries only part of the weight; the block slides at constant speed when mg sin θ = μ_kmg cos θ, i.e. tan θ = μ_k.',src:'milesdown:1554147545662'},
  {s:'Chemistry Equations & Constants',disc:'gen_chem',q:'Using the convention in which W is work done BY the system, which expression gives the first law of thermodynamics?',choices:['ΔU = Q − W','ΔU = Q + W','ΔU = W − Q','ΔU = −Q − W'],ans:0,exp:'**ΔU = Q − W**: ΔU is the change in internal energy (J), Q is heat added TO the system (J) and W is work done BY the system (J). Chemistry texts often write ΔU = q + w with w defined as work done ON the system; the physics is identical, only the sign convention for work differs, so always check which one a passage uses.',src:'milesdown:1554147575293'},
  {s:'Chemistry Equations & Constants',disc:'gen_chem',q:'Which expression gives the internal energy of n moles of a monatomic ideal gas at temperature T?',choices:['U = (3/2)nRT','U = nRT','U = (1/2)nRT','U = (5/2)nRT'],ans:0,exp:'**U = (3/2)nRT**: n is moles, R = 8.314 J/(mol·K) and T is absolute temperature (K); each atom has three translational degrees of freedom worth ½RT per mole. Internal energy of an ideal gas depends only on T, so isothermal processes have ΔU = 0; (5/2)nRT applies to diatomic gases, and nRT equals PV, not U.',src:'milesdown:1554147996981'},
  {s:'Chemistry Equations & Constants',disc:'gen_chem',q:'Which expression gives the work done ON a gas by its surroundings when it changes volume at constant external pressure?',choices:['W = −PΔV','W = PΔV','W = −VΔP','W = −PΔV/T'],ans:0,exp:'**W_on = −PΔV**: P is the external pressure (Pa) and ΔV is the volume change (m³), giving joules (1 L·atm ≈ 101 J). Compression (ΔV < 0) means positive work is done on the gas; the work done BY the gas is +PΔV, the area under the P–V curve, and a constant-volume process does no PV work.',src:'milesdown:1554148124206'},
  {s:'Chemistry Equations & Constants',disc:'gen_chem',q:'Which expression gives the heat absorbed or released when a substance changes temperature without changing phase?',choices:['q = mcΔT','q = mΔT/c','q = cΔT/m','q = mc/ΔT'],ans:0,exp:'**q = mcΔT**: q is heat (J), m is mass (g), c is specific heat (J/(g·K); water = 4.184 J/(g·K) = 1 cal/(g·°C)) and ΔT = T_final − T_initial. Because a kelvin and a degree Celsius are the same size, ΔT is the same in either; positive q means heat absorbed.',src:'milesdown:1554148267490'},
  {s:'Chemistry Equations & Constants',disc:'gen_chem',q:'Which expression gives the heat required to melt or boil a mass m of a substance at its transition temperature?',choices:['q = mL','q = mcΔT','q = mLΔT','q = L/m'],ans:0,exp:'**q = mL**: m is mass (g or kg) and L is the latent heat (heat of transformation, J/g), e.g. about 334 J/g for melting ice and 2260 J/g for boiling water. Temperature stays constant during a phase change (ΔT = 0), so q = mcΔT would wrongly predict zero heat.',src:'milesdown:1554148408998'},
  {s:'Chemistry Equations & Constants',disc:'gen_chem',q:'Which expression relates the Gibbs free energy change to the enthalpy change, entropy change and absolute temperature?',choices:['ΔG = ΔH − TΔS','ΔG = ΔH + TΔS','ΔG = ΔS − TΔH','ΔG = TΔH − ΔS'],ans:0,exp:'**ΔG = ΔH − TΔS**: ΔH is enthalpy change (kJ/mol), ΔS is entropy change (often J/(mol·K), so convert to kJ) and T is in kelvin. ΔG < 0 means spontaneous; a reaction with ΔH < 0 and ΔS > 0 is spontaneous at all temperatures, while opposite signs make spontaneity temperature-dependent.',src:'milesdown:1554149282610'},
  {s:'Chemistry Equations & Constants',disc:'gen_chem',q:'Which expression gives the standard enthalpy of reaction from standard heats of formation?',choices:['ΔH°rxn = ΣΔH°f(products) − ΣΔH°f(reactants)','ΔH°rxn = ΣΔH°f(reactants) − ΣΔH°f(products)','ΔH°rxn = ΣΔH°f(products) + ΣΔH°f(reactants)','ΔH°rxn = [ΣΔH°f(products) − ΣΔH°f(reactants)]/T'],ans:0,exp:'**ΔH°rxn = ΣΔH°f(products) − ΣΔH°f(reactants)** ("products minus reactants"), with each ΔH°f (kJ/mol) multiplied by its stoichiometric coefficient; elements in their standard states have ΔH°f = 0. This is a consequence of Hess\'s law; do not confuse it with the bond-energy method, which is reactants minus products.',src:'milesdown:1554149612304'},
  {s:'Chemistry Equations & Constants',disc:'gen_chem',q:'Which expression is the ideal gas law?',choices:['PV = nRT','PV = RT/n','P/V = nRT','PV = nR/T'],ans:0,exp:'**PV = nRT**: P is pressure, V is volume, n is moles, T is absolute temperature (K) and R is the gas constant, 0.0821 L·atm/(mol·K) for atm and liters or 8.314 J/(mol·K) for Pa and m³. Sanity check: at STP (273 K, 1 atm) one mole occupies about 22.4 L, and temperature must always be in kelvin.',src:'milesdown:1554149858343'},
  {s:'Chemistry Equations & Constants',disc:'gen_chem',q:'Which expression is the Henderson–Hasselbalch equation for a buffer of weak acid HA and conjugate base A⁻?',choices:['pH = pKa + log([A⁻]/[HA])','pH = pKa + log([HA]/[A⁻])','pH = pKa + ln([A⁻]/[HA])','pH = pKa × log([A⁻]/[HA])'],ans:0,exp:'**pH = pKa + log([A⁻]/[HA])**: pKa = −log Ka, [A⁻] is the conjugate-base concentration and [HA] the weak-acid concentration (M). When [A⁻] = [HA] (half-equivalence) pH = pKa, and more base raises pH; inverting the ratio predicts the wrong direction. A buffer works best within about ±1 pH unit of its pKa.',src:'milesdown:1554149949432'},
  {s:'Chemistry Equations & Constants',disc:'gen_chem',q:'Which expression defines molarity (M)?',choices:['moles of solute / liters of solution','moles of solute / kilograms of solvent','moles of solute / liters of solvent','grams of solute / liters of solution'],ans:0,exp:'**Molarity = mol solute / L solution** (mol/L). The denominator is the total solution volume, not the solvent volume; moles per kilogram of solvent is molality. Because volume expands with temperature, molarity changes slightly with temperature.',src:'milesdown:1554150021808'},
  {s:'Chemistry Equations & Constants',disc:'gen_chem',q:'Which expression defines molality (m)?',choices:['moles of solute / kilograms of solvent','moles of solute / kilograms of solution','moles of solute / liters of solution','grams of solute / kilograms of solvent'],ans:0,exp:'**Molality = mol solute / kg solvent** (mol/kg). Mass does not change with temperature, which is why molality is used in the freezing-point and boiling-point equations. For dilute aqueous solutions molality ≈ molarity, because 1 L of water has a mass of about 1 kg.',src:'milesdown:1554150142666'},
  {s:'Chemistry Equations & Constants',disc:'gen_chem',q:'Which expression gives pH in terms of hydrogen-ion concentration?',choices:['pH = −log[H⁺]','pH = log[H⁺]','pH = −ln[H⁺]','pH = −log[OH⁻]'],ans:0,exp:'**pH = −log[H⁺]**, with [H⁺] (or [H₃O⁺]) in mol/L; the log is base 10. The inverse is [H⁺] = 10^(−pH), so pH 3 means [H⁺] = 10⁻³ M; each pH unit is a tenfold change in [H⁺], and at 25 °C pH + pOH = 14. −log[OH⁻] is pOH, not pH.',src:'milesdown:1554150160161'},
  {s:'Chemistry Equations & Constants',disc:'gen_chem',q:'Which expression relates concentrations and volumes before and after diluting a solution?',choices:['M₁V₁ = M₂V₂','M₁V₂ = M₂V₁','M₁/V₁ = M₂/V₂','M₁V₁² = M₂V₂²'],ans:0,exp:'**M₁V₁ = M₂V₂**: M is molarity (mol/L) and V is volume (any unit, as long as both sides match). It works because moles of solute (M × V) are unchanged by adding solvent; V₂ is the final total volume, not the volume of water added. Sanity check: diluting to twice the volume halves the concentration.',src:'milesdown:1554150172811'},
  {s:'Chemistry Equations & Constants',disc:'gen_chem',q:'Which expression gives the osmotic pressure of a dilute solution?',choices:['Π = iMRT','Π = MRT/i','Π = iMR/T','Π = iRT/M'],ans:0,exp:'**Π = iMRT**: i is the van\'t Hoff factor (about 2 for NaCl, 1 for glucose), M is molarity (mol/L), R = 0.0821 L·atm/(mol·K) and T is temperature (K), giving atm. Osmotic pressure rises with both particle concentration and temperature, so neither should appear in a denominator.',src:'milesdown:1554150225745'},
  {s:'Chemistry Equations & Constants',disc:'gen_chem',q:'Which expression gives the freezing-point depression of a solution?',choices:['ΔTf = i·Kf·(molality)','ΔTf = i·Kf·(molarity)','ΔTf = Kf·(molality)/i','ΔTf = i·(molality)/Kf'],ans:0,exp:'**ΔTf = iKf·m**: i is the van\'t Hoff factor, Kf is the solvent\'s cryoscopic constant (1.86 °C·kg/mol for water) and m is molality (mol/kg), not molarity. The new freezing point is Tf° − ΔTf; 1 m NaCl (i ≈ 2) lowers water\'s freezing point by about 3.7 °C.',src:'milesdown:1554150320451'},
  {s:'Chemistry Equations & Constants',disc:'gen_chem',q:'Which expression gives the boiling-point elevation of a solution?',choices:['ΔTb = iKb·m','ΔTb = Kb·m/i','ΔTb = iKb/m','ΔTb = iKb·X_solute'],ans:0,exp:'**ΔTb = iKb·m**: i is the van\'t Hoff factor, Kb is the solvent\'s ebullioscopic constant (0.512 °C·kg/mol for water) and m is molality (mol/kg). Like all colligative properties it depends on the number of dissolved particles, so the effect grows with i and m; the new boiling point is Tb° + ΔTb.',src:'milesdown:1554150416107'},
  {s:'Chemistry Equations & Constants',disc:'gen_chem',q:'Which expression gives the mole fraction of component A in a mixture?',choices:['X_A = n_A / n_total','X_A = n_A / n_solvent','X_A = n_total / n_A','X_A = mass_A / mass_total'],ans:0,exp:'**X_A = n_A/n_total**: moles of A divided by total moles of all components, so X is dimensionless and all mole fractions sum to 1. It appears in Raoult\'s law (P_A = X_A·P°_A) and Dalton\'s law (P_A = X_A·P_total); the mass ratio is a mass fraction, a different quantity.',src:'milesdown:1554150429852'},
  {s:'Physics Equations & Units',disc:'physics',q:'Which expression gives the period of a wave in terms of its frequency?',choices:['T = 1/f','T = 2πf','T = λf','T = f/λ'],ans:0,exp:'**T = 1/f**: T is the period (s, time for one full cycle) and f is the frequency (Hz = cycles per second). Sanity check: a 50 Hz wave repeats every 0.02 s; 2πf is angular frequency ω (rad/s) and λf is the wave speed.',src:'milesdown:1554150445362'},
  {s:'Physics Equations & Units',disc:'physics',q:'Which expression is Snell\'s law for light passing from medium 1 into medium 2?',choices:['n₁sin θ₁ = n₂sin θ₂','n₁cos θ₁ = n₂cos θ₂','n₁sin θ₂ = n₂sin θ₁','sin θ₁/n₁ = sin θ₂/n₂'],ans:0,exp:'**n₁sin θ₁ = n₂sin θ₂**: n is each medium\'s index of refraction and θ is measured from the normal, not the surface. Light entering a higher-n medium bends toward the normal; setting θ₂ = 90° gives the critical angle for total internal reflection, sin θc = n₂/n₁ (only when n₁ > n₂).',src:'milesdown:1554150551646'},
  {s:'Physics Equations & Units',disc:'physics',q:'Which expression gives the index of refraction of a medium?',choices:['n = c/v','n = v/c','n = cv','n = c/λ'],ans:0,exp:'**n = c/v**: c = 3.00×10⁸ m/s is the speed of light in vacuum and v is its speed in the medium, so n is dimensionless and always ≥ 1 (water ≈ 1.33, glass ≈ 1.5). v/c would give values below 1, and c/λ is the frequency of the light.',src:'milesdown:1554150566175'},
  {s:'Physics Equations & Units',disc:'physics',q:'Which expression gives the magnification produced by a lens or mirror?',choices:['m = hᵢ/hₒ = −dᵢ/dₒ','m = hᵢ/hₒ = dᵢ/dₒ','m = hₒ/hᵢ = −dᵢ/dₒ','m = hᵢ/hₒ = −dₒ/dᵢ'],ans:0,exp:'**m = hᵢ/hₒ = −dᵢ/dₒ**: hᵢ and hₒ are image and object heights, dᵢ and dₒ are image and object distances (subscript o for object). A negative m means an inverted image (real images are inverted), and |m| > 1 means enlarged; dropping the minus sign would make every real image upright.',src:'milesdown:1554150727905'},
  {s:'Physics Equations & Units',disc:'physics',q:'Which expression is the thin lens (and mirror) equation?',choices:['1/f = 1/dₒ + 1/dᵢ','f = dₒ + dᵢ','1/f = 1/dₒ − 1/dᵢ','f = 1/dₒ + 1/dᵢ'],ans:0,exp:'**1/f = 1/dₒ + 1/dᵢ**: f is focal length, dₒ is object distance and dᵢ is image distance, all in the same length unit. Sign conventions: f > 0 for converging lenses and concave mirrors, and dᵢ > 0 for real images; for a mirror f = R/2. Remember to invert 1/f at the end; leaving it uninverted gives units of 1/length.',src:'milesdown:1554150750579'},
  {s:'Chemistry Equations & Constants',disc:'gen_chem',q:'Which expression gives the energy of the photon emitted when a hydrogen electron drops from level nᵢ to a lower level n_f (R_H = 2.18×10⁻¹⁸ J)?',choices:['E = R_H(1/n_f² − 1/nᵢ²)','E = R_H(1/nᵢ² − 1/n_f²)','E = R_H(1/n_f − 1/nᵢ)','E = R_H(nᵢ² − n_f²)'],ans:0,exp:'**E = hf = R_H(1/n_f² − 1/nᵢ²)**: R_H = 2.18×10⁻¹⁸ J is the Rydberg energy and n are principal quantum numbers; with n_f < nᵢ the result is positive, the energy released. It follows from the Bohr levels Eₙ = −R_H/n²; the wavelength form is 1/λ = R(1/n_f² − 1/nᵢ²) with R = 1.097×10⁷ m⁻¹. Swapping the terms gives a negative photon energy.',src:'milesdown:1554150850127'},
  {s:'Physics Equations & Units',disc:'physics',q:'Which expression gives the sound intensity level β in decibels?',choices:['β = 10 log(I/I₀)','β = 10 ln(I/I₀)','β = 10 log(I₀/I)','β = log(I/I₀)'],ans:0,exp:'**β = 10 log(I/I₀)**: I is the sound intensity (W/m²) and I₀ = 10⁻¹² W/m² is the threshold of hearing; the log is base 10. Each tenfold increase in intensity adds 10 dB (100× adds 20 dB); without the factor of 10 the answer would be in bels.',src:'milesdown:1554150998131'},
  {s:'Physics Equations & Units',disc:'physics',q:'Which expression gives the allowed standing-wave wavelengths in a pipe of length L that is closed at one end and open at the other?',choices:['λ = 4L/n (n = 1, 3, 5, …)','λ = 2L/n (n = 1, 2, 3, …)','λ = 4L/n (n = 1, 2, 3, …)','λ = 2L/n (n = 1, 3, 5, …)'],ans:0,exp:'**λ = 4L/n with odd n only**: L is pipe length (m) and n is the harmonic number. The closed end must be a node and the open end an antinode, so the fundamental fits a quarter wavelength (λ = 4L) and only odd harmonics exist; frequencies are f = nv/(4L).',src:'milesdown:1554151016840'},
  {s:'Physics Equations & Units',disc:'physics',q:'Which expression gives the allowed standing-wave wavelengths for a string fixed at both ends, or a pipe open at both ends, of length L?',choices:['λ = 2L/n (n = 1, 2, 3, …)','λ = 4L/n (n = 1, 3, 5, …)','λ = 4L/n (n = 1, 2, 3, …)','λ = 2L/n (n = 1, 3, 5, …)'],ans:0,exp:'**λ = 2L/n with all integers n**: L is pipe length (m) and n is the harmonic number. An open pipe has antinodes at both ends and a string has nodes at both ends; either way the length holds a whole number of half-wavelengths (L = nλ/2), so the fundamental is λ = 2L and every harmonic is allowed. Combining with v = fλ gives f = nv/(2L).',src:'milesdown:1554151067087'},
  {s:'Physics Equations & Units',disc:'physics',q:'Which expression gives the beat frequency heard when two sound waves of slightly different frequencies f₁ and f₂ overlap?',choices:['f_beat = |f₁ − f₂|','f_beat = f₁ + f₂','f_beat = (f₁ + f₂)/2','f_beat = |f₁ − f₂|/2'],ans:0,exp:'**f_beat = |f₁ − f₂|**, in Hz. For example, 440 Hz and 444 Hz produce 4 beats per second, which is how musicians tune by ear. The average (f₁ + f₂)/2 is the pitch actually heard, not the rate at which loudness pulses.',src:'milesdown:1554151116478'},
  {s:'Physics Equations & Units',disc:'physics',q:'A sound source and an observer are moving toward each other. Which expression gives the frequency the observer hears?',choices:['f′ = f(v + vₒ)/(v − vₛ)','f′ = f(v − vₒ)/(v + vₛ)','f′ = f(v + vₛ)/(v − vₒ)','f′ = f(v − vₒ)/(v − vₛ)'],ans:0,exp:'**f′ = f(v + vₒ)/(v − vₛ)** for approach: f is the emitted frequency, v is the speed of sound (about 343 m/s in air), vₒ is observer speed and vₛ is source speed. The general form is f′ = f(v ± vₒ)/(v ∓ vₛ), with the top signs for motion toward each other. Sanity check: approach must raise the pitch, so the numerator grows and the denominator shrinks.',src:'milesdown:1554151136934'},
  {s:'Physics Equations & Units',disc:'physics',q:'Which expression defines density?',choices:['ρ = m/V','ρ = V/m','ρ = mV','ρ = mg/V'],ans:0,exp:'**ρ = m/V**: m is mass (kg) and V is volume (m³), giving kg/m³ (or g/cm³). Water is 1 g/cm³ = 1000 kg/m³, and specific gravity is ρ/ρ_water; mg/V is weight per volume (specific weight), not density.',src:'milesdown:1554151205157'},
  {s:'Physics Equations & Units',disc:'physics',q:'Which expression defines pressure?',choices:['P = F/A','P = FA','P = A/F','P = F/A²'],ans:0,exp:'**P = F/A**: F is the force acting perpendicular to a surface (N) and A is the area (m²), giving pascals (1 Pa = 1 N/m²). 1 atm = 101,325 Pa ≈ 1.01×10⁵ Pa; spreading the same force over a larger area lowers the pressure.',src:'milesdown:1554151226202'},
  {s:'Physics Equations & Units',disc:'physics',q:'Which expression gives the absolute pressure at depth h in a fluid open to the atmosphere?',choices:['P = P₀ + ρgh','P = ρgh','P = P₀ − ρgh','P = P₀ + ½ρgh'],ans:0,exp:'**P = P₀ + ρgh**: P₀ is the pressure at the surface (usually 1 atm), ρ is fluid density (kg/m³), g ≈ 9.8 m/s² and h is depth (m). ρgh alone is the gauge pressure; about 10 m of water adds roughly 1 atm, so pressure 10 m down is about 2 atm absolute.',src:'milesdown:1554151245562'},
  {s:'Physics Equations & Units',disc:'physics',q:'Which expression gives the buoyant force on an object immersed in a fluid?',choices:['F_b = ρ_fluid·V_submerged·g','F_b = ρ_object·V_submerged·g','F_b = ρ_fluid·V_submerged/g','F_b = ρ_fluid·g·h'],ans:0,exp:'**F_b = ρ_fluid·V_submerged·g** (Archimedes\' principle): ρ_fluid is the fluid density (kg/m³), V_submerged is the displaced volume (m³) and g ≈ 9.8 m/s², so F_b equals the weight of displaced fluid. The object\'s own density does not appear; an object floats if ρ_object < ρ_fluid, i.e. if the buoyant force at full submersion exceeds its weight mg.',src:'milesdown:1554151349057'},
  {s:'Physics Equations & Units',disc:'physics',q:'Which expression gives the volumetric flow rate of a fluid through a pipe?',choices:['Q = Av','Q = v/A','Q = A/v','Q = Av²'],ans:0,exp:'**Q = Av**: A is the cross-sectional area (m²) and v is the average flow speed (m/s), giving m³/s, the volume passing per unit time. For an incompressible fluid Q is constant (continuity, A₁v₁ = A₂v₂), so flow speeds up where the pipe narrows.',src:'milesdown:1554151399717'},
  {s:'Physics Equations & Units',disc:'physics',q:'Which pair of expressions gives the electric potential energy of a charge?',choices:['U = kq₁q₂/r = qV','U = kq₁q₂/r² = qV','U = kq₁q₂/r = q/V','U = kq₁q₂/r = qE'],ans:0,exp:'**U = kq₁q₂/r = qV**: k = 8.99×10⁹ N·m²/C², q₁ and q₂ are charges (coulombs) with signs kept, r is separation (m) and V is the electric potential (J/C) at the charge\'s location. Like charges give positive U; the 1/r² form is Coulomb\'s force, and qE is also a force, not an energy.',src:'milesdown:1554151597603'},
  {s:'Physics Equations & Units',disc:'physics',q:'Which expression is Coulomb\'s law for the magnitude of the force between two point charges?',choices:['F = k|q₁q₂|/r²','F = k|q₁q₂|/r','F = k|q₁|/r²','F = k|q₁q₂|r²'],ans:0,exp:'**F = k|q₁q₂|/r²**: k = 1/(4πε₀) = 8.99×10⁹ N·m²/C², q₁ and q₂ are charges (coulombs) and r is separation (m). Like gravity it is inverse-square, so tripling r cuts F to one ninth; k|q₁q₂|/r has energy units (it is the potential energy).',src:'milesdown:1554151904607'},
  {s:'Physics Equations & Units',disc:'physics',q:'Which expression gives the magnitude of the electric field a distance r from a point charge Q?',choices:['E = kQ/r²','E = kQ/r','E = kQq/r²','E = kQ²/r²'],ans:0,exp:'**E = kQ/r²**: k = 8.99×10⁹ N·m²/C², Q is the source charge (coulombs) and r is distance (m), giving N/C (equivalently V/m). The field does not depend on any test charge; multiplying by a test charge q gives the force, and kQ/r is the potential.',src:'milesdown:1554152002652'},
  {s:'Physics Equations & Units',disc:'physics',q:'Which expression gives the electric potential at a distance r from a point charge Q?',choices:['V = kQ/r','V = kQ/r²','V = kQq/r','V = kr/Q'],ans:0,exp:'**V = kQ/r**: k = 8.99×10⁹ N·m²/C², Q is the source charge (C, sign included) and r is distance (m), giving volts (J/C). Potential is a scalar that falls off as 1/r, not 1/r² like the field, and multiplying by a charge q gives potential energy.',src:'milesdown:1554152161018'},
  {s:'Physics Equations & Units',disc:'physics',q:'Which expression gives the magnetic force on a charge q moving with speed v through a magnetic field of strength B, where θ is the angle between v and B?',choices:['F = qvB sin θ','F = qvB cos θ','F = qB sin θ/v','F = qv sin θ/B'],ans:0,exp:'**F = qvB sin θ**: q is charge (coulombs), v is speed (m/s), B is field strength in teslas and θ is the angle between velocity and field. The force is zero when the charge moves parallel to the field and maximal when perpendicular; it is always perpendicular to v (right-hand rule), so it does no work.',src:'milesdown:1554152431193'},
  {s:'Physics Equations & Units',disc:'physics',q:'Which expression gives the magnetic force on a straight wire of length L carrying current I in a magnetic field of strength B, where θ is the angle between the wire and the field?',choices:['F = ILB sin θ','F = ILB cos θ','F = IB sin θ/L','F = IL sin θ/B'],ans:0,exp:'**F = ILB sin θ**: I is current (amperes), L is the length of wire in the field (m), B is field strength (T) and θ is the angle between current and field. It mirrors F = qvB sin θ, since IL plays the role of qv; a wire parallel to the field feels no force.',src:'milesdown:1554152560322'},
  {s:'Physics Equations & Units',disc:'physics',q:'Which expression is Ohm\'s law?',choices:['V = IR','V = I/R','V = R/I','V = I²R'],ans:0,exp:'**V = IR**: V is the voltage drop across a resistor (V), I is current (amperes) and R is resistance (Ω). For fixed voltage, a larger resistance means less current; I²R is the power dissipated (W), not voltage.',src:'milesdown:1554152573064'},
  {s:'Physics Equations & Units',disc:'physics',q:'Which expression gives the uniform electric field between the plates of a parallel-plate capacitor with voltage V across a gap d?',choices:['E = V/d','E = Vd','E = V/d²','E = kV/d²'],ans:0,exp:'**E = V/d**: V is the potential difference between the plates (V) and d is the plate separation (m), giving V/m (= N/C). Equivalently E = Q/(ε₀A). The field between the plates is uniform, so point-charge forms with 1/d² do not apply.',src:'milesdown:1554152624521'},
  {s:'Physics Equations & Units',disc:'physics',q:'Which expression gives the charge stored on a capacitor?',choices:['Q = CV','Q = C/V','Q = V/C','Q = ½CV²'],ans:0,exp:'**Q = CV**: Q is the charge on each plate (coulombs), C is capacitance (F) and V is the voltage across the capacitor (V); this is the definition of capacitance, C = Q/V. ½CV² is the stored energy in joules, not charge.',src:'milesdown:1554152970968'},
  {s:'Physics Equations & Units',disc:'physics',q:'Which expression gives the capacitance of a parallel-plate capacitor with plate area A and separation d (vacuum between the plates)?',choices:['C = ε₀A/d','C = ε₀d/A','C = ε₀A/d²','C = A/(ε₀d)'],ans:0,exp:'**C = ε₀A/d**: ε₀ = 8.85×10⁻¹² F/m is the permittivity of free space, A is plate area (m²) and d is plate separation (m). Bigger plates or a smaller gap store more charge per volt; inserting a dielectric multiplies C by its dielectric constant κ (C = κε₀A/d).',src:'milesdown:1554153194996'},
  {s:'Physics Equations & Units',disc:'physics',q:'Which expression gives the energy stored in a capacitor?',choices:['U = ½CV²','U = CV²','U = ½CV','U = ½C²V'],ans:0,exp:'**U = ½CV²** (equivalently ½QV = Q²/2C): C is capacitance (F) and V is voltage (V), giving joules. The ½ arises because the voltage builds from zero as charge accumulates; ½CV equals half the charge, not energy.',src:'milesdown:1554153362956'},
  {s:'Chemistry Equations & Constants',disc:'gen_chem',q:'Which expression gives the standard cell potential (emf) of an electrochemical cell from standard reduction potentials?',choices:['E°cell = E°red(cathode) − E°red(anode)','E°cell = E°red(anode) − E°red(cathode)','E°cell = E°red(cathode) + E°red(anode)','E°cell = [E°red(cathode) − E°red(anode)]/n'],ans:0,exp:'**E°cell = E°red(cathode) − E°red(anode)**, using both electrodes\' standard reduction potentials (V). For the Zn/Cu cell: 0.34 − (−0.76) = +1.10 V. A positive E°cell means a spontaneous (galvanic) cell, linked by ΔG° = −nFE°cell; potentials are intensive, so never multiply or divide them by electron counts or coefficients.',src:'milesdown:1554153475272'},
  {s:'Physics Equations & Units',disc:'physics',q:'Which expression gives the resistance of a wire of length L and cross-sectional area A?',choices:['R = ρL/A','R = ρA/L','R = LA/ρ','R = ρL/A²'],ans:0,exp:'**R = ρL/A**: ρ is the material\'s resistivity (Ω·m), L is length (m) and A is cross-sectional area (m²), giving ohms. A longer wire resists more and a thicker wire resists less, just as a long narrow blood vessel resists flow more than a short wide one.',src:'milesdown:1554153914092'},
  {s:'Physics Equations & Units',disc:'physics',q:'Which expression gives the root-mean-square voltage of a sinusoidal alternating current source?',choices:['V_rms = V_max/√2','V_rms = √2·V_max','V_rms = V_max/2','V_rms = V_max²/2'],ans:0,exp:'**V_rms = V_max/√2 ≈ 0.707 V_max**: V_max is the peak voltage. Rated AC voltages are rms values, so a 120 V US outlet actually peaks near 170 V; an rms value can never exceed the peak, which rules out √2·V_max.',src:'milesdown:1554154258069'},
  {s:'Physics Equations & Units',disc:'physics',q:'Which expression gives the root-mean-square current in a sinusoidal alternating current circuit?',choices:['I_rms = I_max/√2','I_rms = √2·I_max','I_rms = I_max/2','I_rms = 2I_max/π'],ans:0,exp:'**I_rms = I_max/√2 ≈ 0.707 I_max**: I_max is the peak current (amperes). The rms value is the steady DC current that would dissipate the same average power, so P_avg = I_rms²R; 2I_max/π is the average of a rectified sine wave, a different quantity.',src:'milesdown:1554154354165'},
  {s:'Physics Equations & Units',disc:'physics',q:'Which expression gives the equivalent resistance of resistors connected in series?',choices:['R_eq = R₁ + R₂ + …','1/R_eq = 1/R₁ + 1/R₂ + …','R_eq = 1/R₁ + 1/R₂ + …','R_eq = R₁R₂…'],ans:0,exp:'**R_eq = R₁ + R₂ + …**: series resistors carry the same current and their voltage drops add, so resistances simply add (in Ω). Sanity check: the total must be larger than the largest single resistor; the reciprocal sum is the parallel rule.',src:'milesdown:1554154503067'},
  {s:'Physics Equations & Units',disc:'physics',q:'Which expression gives the equivalent resistance of resistors connected in parallel?',choices:['1/R_eq = 1/R₁ + 1/R₂ + …','R_eq = R₁ + R₂ + …','R_eq = 1/R₁ + 1/R₂ + …','1/R_eq = R₁ + R₂ + …'],ans:0,exp:'**1/R_eq = 1/R₁ + 1/R₂ + …**: parallel branches share the same voltage and their currents add, so conductances add. The result is always smaller than the smallest resistor (two equal resistors give R/2); a classic error is forgetting to invert the sum at the end.',src:'milesdown:1554154521721'},
  {s:'Physics Equations & Units',disc:'physics',q:'Which expression gives the equivalent capacitance of capacitors connected in series?',choices:['1/C_eq = 1/C₁ + 1/C₂ + …','C_eq = C₁ + C₂ + …','C_eq = 1/C₁ + 1/C₂ + …','1/C_eq = C₁ + C₂ + …'],ans:0,exp:'**1/C_eq = 1/C₁ + 1/C₂ + …**: series capacitors carry the same charge and their voltages add, so reciprocals add and C_eq is smaller than the smallest capacitor. Mnemonic: capacitors combine opposite to resistors (series capacitors look like parallel resistors).',src:'milesdown:1554154532519'},
  {s:'Physics Equations & Units',disc:'physics',q:'Which expression gives the equivalent capacitance of capacitors connected in parallel?',choices:['C_eq = C₁ + C₂ + …','1/C_eq = 1/C₁ + 1/C₂ + …','C_eq = 1/C₁ + 1/C₂ + …','1/C_eq = C₁ + C₂ + …'],ans:0,exp:'**C_eq = C₁ + C₂ + …**: parallel capacitors share the same voltage, and connecting them effectively enlarges the plate area (C = ε₀A/d), so capacitances add (in F). The total exceeds the largest capacitor, the opposite of parallel resistors.',src:'milesdown:1554154548545'},
  {s:'Chemistry Equations & Constants',disc:'gen_chem',q:'Which pair of values correctly gives the ideal gas constant R?',choices:['8.314 J/(mol·K) = 0.0821 L·atm/(mol·K)','0.0821 J/(mol·K) = 8.314 L·atm/(mol·K)','8.314 kJ/(mol·K) = 0.0821 L·atm/(mol·K)','1.987 J/(mol·K) = 0.0821 L·atm/(mol·K)'],ans:0,exp:'**R = 8.314 J/(mol·K) = 0.0821 L·atm/(mol·K)** (also 1.987 cal/(mol·K)). Use 8.314 with energies in joules (ΔG° = −RT ln K, Arrhenius) and 0.0821 with gas problems in liters and atmospheres. Converting checks out: 0.0821 L·atm × 101.3 J/(L·atm) ≈ 8.31 J.',src:'milesdown:1554154591162'},
  {s:'Chemistry Equations & Constants',disc:'gen_chem',q:'What is the value of Planck\'s constant, h?',choices:['6.626×10⁻³⁴ J·s','6.626×10⁻³⁴ J/s','6.626×10³⁴ J·s','6.022×10⁻³⁴ J·s'],ans:0,exp:'**h = 6.626×10⁻³⁴ J·s** (= kg·m²/s), the proportionality constant in E = hf. The unit must be J·s so that multiplying by frequency (1/s) gives energy; J/s is a watt. A handy combination is hc ≈ 1.99×10⁻²⁵ J·m; 6.022 belongs to Avogadro\'s number.',src:'milesdown:1554154602817'},
  {s:'Chemistry Equations & Constants',disc:'gen_chem',q:'Which set of values correctly gives the density of liquid water?',choices:['1 g/cm³ = 1 kg/L = 1000 kg/m³','1 g/cm³ = 1 g/L = 1 kg/m³','1 g/cm³ = 1 kg/L = 100 kg/m³','1 kg/cm³ = 1 kg/L = 1000 kg/m³'],ans:0,exp:'**ρ_water = 1 g/cm³ = 1 g/mL = 1 kg/L = 1000 kg/m³** (at about 4 °C; very close at room temperature). Check: 1 m³ = 1000 L, and each liter has a mass of 1 kg. MCAT tip: specific gravity compares a substance\'s density to this value, and objects with ρ < 1 g/cm³ float in water.',src:'milesdown:1554154619650'},
  {s:'Chemistry Equations & Constants',disc:'gen_chem',q:'What is the value of the Faraday constant, F?',choices:['≈ 96,485 C/mol e⁻','≈ 96,485 J/mol e⁻','≈ 6.022×10²³ C/mol e⁻','≈ 1.602×10⁻¹⁹ C/mol e⁻'],ans:0,exp:'**F ≈ 96,485 C/mol e⁻** (often rounded to 96,500 or ~10⁵), the charge carried by one mole of electrons. It equals Avogadro\'s number × the elementary charge: 6.022×10²³ × 1.602×10⁻¹⁹ C ≈ 96,485 C. It appears in ΔG° = −nFE° and in electrolysis (moles of e⁻ = It/F).',src:'milesdown:1554154676040'},
  {s:'Physics Equations & Units',disc:'physics',q:'What is the newton (N) expressed in SI base units?',choices:['kg·m/s²','kg·m²/s²','kg·m/s','kg/(m·s²)'],ans:0,exp:'**1 N = 1 kg·m/s²**, from F = ma (mass in kg times acceleration in m/s²). kg·m²/s² is the joule, kg·m/s is momentum and kg/(m·s²) is the pascal.',src:'milesdown:1554154690043'},
  {s:'Physics Equations & Units',disc:'physics',q:'What is the joule (J) expressed in SI base units?',choices:['kg·m²/s²','kg·m/s²','kg·m²/s³','kg·m²/s'],ans:0,exp:'**1 J = 1 N·m = 1 kg·m²/s²**, from W = Fd or KE = ½mv². kg·m²/s³ is the watt (J/s) and kg·m/s² is the newton; a quick check is that ½mv² gives kg × (m/s)².',src:'milesdown:1554154705687'},
  {s:'Physics Equations & Units',disc:'physics',q:'What is the pascal (Pa) expressed in other SI units?',choices:['N/m² = kg/(m·s²)','N·m² = kg·m³/s²','N/m = kg/s²','N/m³ = kg/(m²·s²)'],ans:0,exp:'**1 Pa = 1 N/m² = 1 kg/(m·s²)**, from P = F/A. Atmospheric pressure is about 1.01×10⁵ Pa (101 kPa = 760 mmHg); N/m is the unit of a spring constant or surface tension, not pressure.',src:'milesdown:1554154771004'},
  {s:'Physics Equations & Units',disc:'physics',q:'Which combination of units is equivalent to the volt (V)?',choices:['J/C','C/J','J·C','C/s'],ans:0,exp:'**1 V = 1 J/C**: electric potential is potential energy per unit charge (V = U/q). C/s is the ampere; check with U = qV, since coulombs × volts must give joules.',src:'milesdown:1554154824909'},
  {s:'Physics Equations & Units',disc:'physics',q:'Which combination of units is equivalent to the ohm (Ω)?',choices:['V/A','A/V','V·A','C/V'],ans:0,exp:'**1 Ω = 1 V/A**, from Ohm\'s law R = V/I. V·A is the watt (power) and C/V is the farad (capacitance); A/V is the siemens, the unit of conductance.',src:'milesdown:1554154920511'},
  {s:'Physics Equations & Units',disc:'physics',q:'Which combination of units is equivalent to the ampere, A?',choices:['C/s','s/C','C·s','J/C'],ans:0,exp:'**1 A = 1 C/s**: current is the rate of charge flow, I = Q/t. J/C is the volt; a sanity check is that 1 A for 1 s moves 1 C of charge.',src:'milesdown:1554154930792'},
  {s:'Physics Equations & Units',disc:'physics',q:'Which combination of units is equivalent to the farad (F)?',choices:['C/V','V/C','C·V','J/C'],ans:0,exp:'**1 F = 1 C/V**, from C = Q/V: a 1 F capacitor stores 1 C per volt applied. C·V is a joule (energy), and real capacitors are usually in the μF–pF range because a farad is very large.',src:'milesdown:1554154939044'},
  {s:'Physics Equations & Units',disc:'physics',q:'Which pair of unit combinations is equivalent to the watt (W)?',choices:['J/s = V·A','J·s = V·A','J/s = V/A','J·s = V/A'],ans:0,exp:'**1 W = 1 J/s = 1 V·A**: power is energy per time, and electrically P = IV. V/A is the ohm and J·s is the unit of Planck\'s constant (action), not power.',src:'milesdown:1554154948463'},
  {s:'Chemistry Equations & Constants',disc:'gen_chem',q:'Which expression is the Arrhenius equation for a rate constant?',choices:['k = Ae^(−Ea/RT)','k = Ae^(Ea/RT)','k = Ae^(−RT/Ea)','k = Ae^(−Ea·RT)'],ans:0,exp:'**k = Ae^(−Ea/RT)**: k is the rate constant, A is the frequency (pre-exponential) factor, Ea is activation energy (J/mol), R = 8.314 J/(mol·K) and T is temperature (K). Sanity check: raising T or lowering Ea (e.g. with a catalyst) must increase k, which only the −Ea/RT exponent does; ln k = ln A − Ea/(RT), so a plot of ln k vs 1/T has slope −Ea/R.',src:'milesdown:1554171449249'},
  {s:'Chemistry Equations & Constants',disc:'gen_chem',q:'Which expression gives the enthalpy of reaction from bond dissociation energies?',choices:['ΔH°rxn = ΣBDE(bonds broken) − ΣBDE(bonds formed)','ΔH°rxn = ΣBDE(bonds formed) − ΣBDE(bonds broken)','ΔH°rxn = ΣBDE(bonds broken) + ΣBDE(bonds formed)','ΔH°rxn = ΣΔH°f(bonds formed) − ΣBDE(bonds broken)'],ans:0,exp:'**ΔH°rxn = Σ(bonds broken) − Σ(bonds formed)**, i.e. reactant bond energies minus product bond energies (kJ/mol). Breaking bonds costs energy and forming bonds releases it, so a reaction that forms stronger bonds than it breaks is exothermic. This is the reverse of the heats-of-formation rule (products minus reactants), a frequent trap.',src:'milesdown:1554180204281'},
  {s:'Chemistry Equations & Constants',disc:'gen_chem',q:'Which expression gives the standard entropy change of a reaction?',choices:['ΔS°rxn = ΣS°(products) − ΣS°(reactants)','ΔS°rxn = ΣS°(reactants) − ΣS°(products)','ΔS°rxn = ΣS°(products) + ΣS°(reactants)','ΔS°rxn = [ΣS°(products) − ΣS°(reactants)]/T'],ans:0,exp:'**ΔS°rxn = ΣS°(products) − ΣS°(reactants)**, using absolute standard molar entropies (J/(mol·K)) multiplied by stoichiometric coefficients. Unlike ΔH°f, the S° of an element in its standard state is not zero. Quick check: reactions that make more moles of gas usually have ΔS° > 0.',src:'milesdown:1554206508258'},
  {s:'Chemistry Equations & Constants',disc:'gen_chem',q:'Which expression relates the standard free energy change of a reaction to its equilibrium constant?',choices:['ΔG° = −RT ln K','ΔG° = RT ln K','ΔG° = −RT/ln K','ΔG° = −ln K/(RT)'],ans:0,exp:'**ΔG° = −RT ln K_eq**: R = 8.314 J/(mol·K), T is temperature (K) and K_eq is the equilibrium constant. If K > 1, ln K > 0 and ΔG° < 0 (products favored at equilibrium); if K = 1, ΔG° = 0. It pairs with ΔG° = −nFE°cell in electrochemistry.',src:'milesdown:1554206631612'},
  {s:'Chemistry Equations & Constants',disc:'gen_chem',q:'Which expression gives the free energy change of a reaction under non-standard conditions, in terms of the reaction quotient Q?',choices:['ΔG = ΔG° + RT ln Q','ΔG = ΔG° − RT ln Q','ΔG = ΔG° + RT ln K','ΔG = RT ln(K/Q)'],ans:0,exp:'**ΔG = ΔG° + RT ln Q**, which is equivalent to ΔG = RT ln(Q/K) since ΔG° = −RT ln K; R = 8.314 J/(mol·K) and T is in kelvin. If Q < K, ΔG < 0 and the reaction proceeds forward; at equilibrium Q = K and ΔG = 0. RT ln(K/Q) has the sign flipped.',src:'milesdown:1554206949122'},
  {s:'Physics Equations & Units',disc:'physics',q:'Which expression is Hooke\'s law for the force exerted by a spring displaced a distance x from equilibrium?',choices:['F = −kx','F = kx²','F = −½kx²','F = −x/k'],ans:0,exp:'**F = −kx**: k is the spring constant (N/m) and x is displacement from equilibrium (m). The minus sign means the restoring force always points back toward equilibrium, opposite the displacement; ½kx² is the stored potential energy, not the force.',src:'milesdown:1554663627634'},
  {s:'Physics Equations & Units',disc:'physics',q:'Which expression is Bernoulli\'s equation for an ideal fluid flowing between two points?',choices:['P₁ + ½ρv₁² + ρgh₁ = P₂ + ½ρv₂² + ρgh₂','P₁ + ρv₁² + ρgh₁ = P₂ + ρv₂² + ρgh₂','P₁ + ½ρv₁ + ρgh₁ = P₂ + ½ρv₂ + ρgh₂','P₁ − ½ρv₁² + ρgh₁ = P₂ − ½ρv₂² + ρgh₂'],ans:0,exp:'**P + ½ρv² + ρgh = constant**: P is pressure (Pa), ρ is fluid density (kg/m³), v is flow speed (m/s) and h is height (m); each term is energy per unit volume (J/m³ = Pa). It is conservation of energy for an incompressible, nonviscous fluid in steady flow, and it implies the Venturi effect: where fluid speeds up, its pressure drops.',src:'milesdown:1554821282601'},
  {s:'Physics Equations & Units',disc:'physics',q:'Which expression gives the ideal mechanical advantage of a frictionless inclined plane of slope length L that rises to height h?',choices:['MA = L/h','MA = h/L','MA = L·h','MA = h/(L − h)'],ans:0,exp:'**MA = L/h** (slope length over height): pushing a load of weight mg up the ramp takes only mg sin θ = mg(h/L), so MA = F_out/F_in = L/h. A 12 m ramp rising 4 m has MA = 3; the force drops by 3× but the distance triples, so the work (mgh) is unchanged, as energy conservation requires.',src:'milesdown:1554158210031'},
  {s:'Physics Equations & Units',disc:'physics',q:'Which expression relates the speed of a wave to its frequency and wavelength?',choices:['v = fλ','v = f/λ','v = λ/f','v = 2πfλ'],ans:0,exp:'**v = fλ**: v is wave speed (m/s), f is frequency (Hz = 1/s) and λ is wavelength (m); units check: (1/s)(m) = m/s. Wave speed is set by the medium, so when a wave enters a new medium its frequency stays fixed and λ changes; for light in vacuum c = fλ.',src:'milesdown:1555857959161'},
  {s:'Physics Equations & Units',disc:'physics',q:'Which expression gives the maximum kinetic energy of an electron ejected in the photoelectric effect by light of frequency f?',choices:['K_max = hf − W','K_max = hf + W','K_max = W − hf','K_max = hf/W'],ans:0,exp:'**K_max = hf − W**: h = 6.626×10⁻³⁴ J·s, f is light frequency (Hz) and W (also written Φ) is the metal\'s work function, the minimum energy to free an electron (J or eV). No electrons are emitted below the threshold frequency f₀ = W/h; raising light intensity ejects more electrons but does not raise K_max.',src:'milesdown:1555890704851'},
  {s:'Chemistry Equations & Constants',disc:'gen_chem',q:'For a zero-order reaction A → products, which pair gives the rate law and the integrated rate law?',choices:['rate = k; [A] = [A]₀ − kt','rate = k[A]; [A] = [A]₀ − kt','rate = k; [A] = [A]₀e^(−kt)','rate = k; 1/[A] = 1/[A]₀ + kt'],ans:0,exp:'**rate = k and [A] = [A]₀ − kt**: k is the rate constant (M/s) and [A]₀ is the initial concentration. The rate does not depend on [A] (e.g. a saturated enzyme or surface catalyst), so a plot of [A] vs t is a straight line with slope −k and the half-life, [A]₀/(2k), shrinks as [A] falls.',src:'milesdown:1554163843264'},
  {s:'Chemistry Equations & Constants',disc:'gen_chem',q:'For a first-order reaction A → products, which pair gives the rate law and the integrated rate law?',choices:['rate = k[A]; [A] = [A]₀e^(−kt)','rate = k[A]; [A] = [A]₀ − kt','rate = k[A]²; [A] = [A]₀e^(−kt)','rate = k[A]; [A] = [A]₀e^(kt)'],ans:0,exp:'**rate = k[A] and [A] = [A]₀e^(−kt)** (equivalently ln[A] = ln[A]₀ − kt): k is the rate constant (s⁻¹). A plot of ln[A] vs t is linear with slope −k, and the half-life t½ = 0.693/k is constant, as in radioactive decay. A positive exponent would make the reactant grow instead of decay.',src:'milesdown:1554169437654'},
  {s:'Chemistry Equations & Constants',disc:'gen_chem',q:'For a second-order reaction A → products, which pair gives the rate law and the integrated rate law?',choices:['rate = k[A]²; 1/[A] = 1/[A]₀ + kt','rate = k[A]²; 1/[A] = 1/[A]₀ − kt','rate = k[A]; 1/[A] = 1/[A]₀ + kt','rate = k[A]²; [A] = [A]₀e^(−kt)'],ans:0,exp:'**rate = k[A]² and 1/[A] = 1/[A]₀ + kt**: k is the rate constant (M⁻¹·s⁻¹). A plot of 1/[A] vs t is linear with positive slope k, because 1/[A] rises as [A] falls; the half-life 1/(k[A]₀) grows as the reaction proceeds. The minus-sign version would make 1/[A] decrease, i.e. [A] increase.',src:'milesdown:1554169565269'},
  {s:'Chemistry Equations & Constants',disc:'gen_chem',q:'Which expression defines pKa for a weak acid with dissociation constant Ka?',choices:['pKa = −log Ka','pKa = log Ka','pKa = −ln Ka','pKa = 10^(−Ka)'],ans:0,exp:'**pKa = −log Ka** (base-10 log), so Ka = 10^(−pKa). A smaller pKa means a larger Ka and a stronger acid: acetic acid (Ka ≈ 1.8×10⁻⁵) has pKa ≈ 4.74. Without the minus sign, weak acids would have negative pKa values.',src:'milesdown:1559952252954'},
  {s:'Chemistry Equations & Constants',disc:'gen_chem',q:'Which expression defines pKb for a weak base with dissociation constant Kb?',choices:['pKb = −log Kb','pKb = log Kb','pKb = −log(Kw/Kb)','pKb = −log(Kw·Kb)'],ans:0,exp:'**pKb = −log Kb** (base-10 log); a smaller pKb means a stronger base. For a conjugate acid–base pair at 25 °C, Ka·Kb = Kw = 1.0×10⁻¹⁴, so pKa + pKb = 14; −log(Kw/Kb) is therefore the pKa of the conjugate acid, not pKb.',src:'milesdown:1559952546279'},
  {s:'Chemistry Equations & Constants',disc:'gen_chem',q:'Which expression relates the standard free energy change of a redox reaction to its standard cell potential?',choices:['ΔG° = −nFE°cell','ΔG° = nFE°cell','ΔG° = −nE°cell/F','ΔG° = −FE°cell/n'],ans:0,exp:'**ΔG° = −nFE°cell**: n is moles of electrons transferred, F ≈ 96,485 C/mol e⁻ and E°cell is the standard cell potential (V), giving joules (C·V = J). A positive E°cell gives a negative ΔG° (spontaneous, galvanic), and the sign flip is the key point; it links to ΔG° = −RT ln K.',src:'milesdown:1560029331994'},
  {s:'Chemistry Equations & Constants',disc:'gen_chem',q:'Which expression is the general form of the Nernst equation for cell potential under non-standard conditions?',choices:['E = E° − (RT/nF) ln Q','E = E° + (RT/nF) ln Q','E = E° − (nF/RT) ln Q','E = E° − RT ln Q'],ans:0,exp:'**E = E° − (RT/nF) ln Q**: E° is the standard cell potential (V), R = 8.314 J/(mol·K), T is temperature (K), n is moles of electrons transferred, F ≈ 96,485 C/mol and Q is the reaction quotient. Units check: RT/nF is in volts. As products build up Q rises and E falls, reaching 0 at equilibrium (Q = K), when the battery is dead.',src:'milesdown:1560030338601'},
  {s:'Chemistry Equations & Constants',disc:'gen_chem',q:'At 25 °C, which simplified form of the Nernst equation is correct?',choices:['E = E° − (0.0592/n) log Q','E = E° − (0.0592/n) ln Q','E = E° + (0.0592/n) log Q','E = E° − 0.0592n log Q'],ans:0,exp:'**E = E° − (0.0592 V/n) log Q** at 298 K: 0.0592 V = 2.303RT/F, where 2.303 converts ln to log₁₀, so pairing 0.0592 with ln double-counts that factor. n is moles of electrons transferred and Q the reaction quotient; each tenfold increase in Q lowers E by 0.0592/n V (59 mV for n = 1).',src:'milesdown:1560031458120'},
];
